# DBTITLE 1,L1 Patch Regression Asserts
# MAGIC %python
# MAGIC BURNDOWN_SQL = "SELECT usage_date_eu AS date_eu,\n                   usage_date AS date,\n                   SUM(prepaid_consumed_quantity) AS daily_credits,\n                   ROUND(SUM(prepaid_consumed_quantity) * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2) AS daily_cost_eur\n            FROM silver.fact_environment_credit\n            GROUP BY usage_date_eu, usage_date\n            ORDER BY usage_date\n"
# MAGIC CONSUMPTION_SQL = {"ds_consumption_declining.sql": "WITH ref AS (\n  SELECT\n    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\n  FROM\n    silver.bot_usage\n),\nagent_month AS (\n  SELECT\n    bot_name,\n    DATE_TRUNC('MONTH', usage_date) AS month,\n    SUM(conversations) AS convs\n  FROM\n    silver.bot_usage\n  GROUP BY\n    bot_name,\n    DATE_TRUNC('MONTH', usage_date)\n)\nSELECT\n  cur.bot_name,\n  prev.convs AS prior_month,\n  COALESCE(cur2.convs, 0) AS last_full_month,\n  ROUND((COALESCE(cur2.convs, 0) - prev.convs) * 100.0 / prev.convs, 1) AS change_pct\nFROM\n  (\n    SELECT DISTINCT\n      bot_name\n    FROM\n      agent_month\n  ) cur\n    CROSS JOIN ref r\n    JOIN agent_month prev\n      ON prev.bot_name = cur.bot_name\n      AND prev.month = ADD_MONTHS(r.current_month, -2)\n    LEFT JOIN agent_month cur2\n      ON cur2.bot_name = cur.bot_name\n      AND cur2.month = ADD_MONTHS(r.current_month, -1)\nWHERE\n  prev.convs >= 10\n  AND COALESCE(cur2.convs, 0) < prev.convs * 0.5\nORDER BY\n  change_pct\n", "ds_consumption_abandoned.sql": "WITH ref AS (\n  SELECT\n    MAX(usage_date) AS max_dt\n  FROM\n    silver.bot_usage\n)\nSELECT\n  b.bot_name,\n  SUM(b.conversations) AS lifetime_conversations,\n  COUNT(DISTINCT b.usage_date) AS lifetime_active_days,\n  MAX(b.usage_date) AS last_used,\n  DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use\nFROM\n  silver.bot_usage b CROSS JOIN ref r\nGROUP BY\n  b.bot_name,\n  r.max_dt\nHAVING\n  SUM(b.conversations) >= 20\n  AND MAX(b.usage_date) < DATE_SUB(r.max_dt, 60)\nORDER BY\n  lifetime_conversations DESC\n", "ds_consumption_mom.sql": "WITH monthly AS (\n  SELECT\n    DATE_TRUNC('MONTH', usage_date) AS month,\n    SUM(conversations) AS convs\n  FROM\n    silver.bot_usage\n  GROUP BY\n    DATE_TRUNC('MONTH', usage_date)\n),\nref AS (\n  SELECT\n    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\n  FROM\n    silver.bot_usage\n)\nSELECT\n  prev.convs AS prior_month_conversations,\n  cur.convs AS last_full_month_conversations,\n  ROUND((cur.convs - prev.convs) * 100.0 / prev.convs, 1) AS mom_growth_pct\nFROM\n  ref r\n    JOIN monthly cur\n      ON cur.month = ADD_MONTHS(r.current_month, -1)\n    JOIN monthly prev\n      ON prev.month = ADD_MONTHS(r.current_month, -2)\n", "ds_consumption_agent_detail.sql": "WITH ref AS (\n  SELECT\n    MAX(usage_date) AS max_dt\n  FROM\n    silver.bot_usage\n),\nbot_status AS (\n  SELECT\n    b.bot_name,\n    CASE\n      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 30) THEN 'Active (last 30 days)'\n      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 60) THEN 'Idle (31-60 days)'\n      ELSE 'Dormant (60+ days)'\n    END AS usage_status,\n    MIN(b.usage_date) AS first_used,\n    MAX(b.usage_date) AS last_used,\n    DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use,\n    COUNT(DISTINCT b.usage_date) AS active_days,\n    ROUND(AVG(b.conversations), 2) AS avg_conversations_per_bot_day\n  FROM\n    silver.bot_usage b CROSS JOIN ref r\n  GROUP BY\n    b.bot_name,\n    r.max_dt\n)\nSELECT\n  b.bot_name,\n  b.environment,\n  CASE\n    WHEN b.environment LIKE '%PROD%' THEN 'Production'\n    WHEN LOWER(b.environment) LIKE '%default%' THEN 'Default environment'\n    ELSE 'Dev / Test / Other'\n  END AS environment_type,\n  DATE_TRUNC('MONTH', b.usage_date) AS usage_month,\n  DATE_TRUNC('QUARTER', b.usage_date) AS usage_quarter,\n  CONCAT(\n    YEAR(DATE_TRUNC('QUARTER', b.usage_date)),\n    ' Q',\n    QUARTER(DATE_TRUNC('QUARTER', b.usage_date))\n  ) AS quarter_label,\n  SUM(b.conversations) AS conversations,\n  s.usage_status,\n  s.first_used,\n  s.last_used,\n  s.days_since_last_use,\n  s.active_days,\n  s.avg_conversations_per_bot_day\nFROM\n  silver.bot_usage b\n    JOIN bot_status s\n      ON s.bot_name = b.bot_name\nGROUP BY\n  b.bot_name,\n  b.environment,\n  DATE_TRUNC('MONTH', b.usage_date),\n  DATE_TRUNC('QUARTER', b.usage_date),\n  s.usage_status,\n  s.first_used,\n  s.last_used,\n  s.days_since_last_use,\n  s.active_days,\n  s.avg_conversations_per_bot_day\n"}
# MAGIC
