# MAGIC %python
# MAGIC import json
# MAGIC
# MAGIC DATASETS = json.loads("[{\"dataset\": \"ds_intro_kpis\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              g.total_agents,\\n              g.total_makers,\\n              g.created_last_30d,\\n              c.prepaid_credits,\\n              c.prepaid_cost_eur,\\n              e.payg_credits,\\n              e.payg_cost_eur\\n            FROM (\\n              SELECT\\n                MEASURE(valid_agent_count) AS total_agents,\\n                MEASURE(maker_count) AS total_makers,\\n                MEASURE(created_last_30d) AS created_last_30d\\n              FROM silver.metric_agent_governance\\n            ) g\\n            CROSS JOIN (\\n              SELECT\\n                MEASURE(total_consumption_credits) AS prepaid_credits,\\n                ROUND(MEASURE(total_consumption_cost_eur), 2) AS prepaid_cost_eur\\n              FROM silver.metric_credit_consumption\\n            ) c\\n            CROSS JOIN (\\n              SELECT\\n                MEASURE(pay_as_you_go_credits) AS payg_credits,\\n                ROUND(MEASURE(pay_as_you_go_credits) * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2) AS payg_cost_eur\\n              FROM silver.metric_environment_consumption\\n            ) e\"}, {\"dataset\": \"ds_credit_split\", \"kind\": \"config.source\", \"sql\": \"SELECT b.agent_category,\\n                   ROUND(COALESCE(c.credits, 0), 1) AS credits,\\n                   ROUND(COALESCE(c.cost_eur, 0), 2) AS cost_eur\\n            FROM (\\n              SELECT 'Copilot Studio' AS agent_category, 1 AS sort_order\\n              UNION ALL SELECT 'Agent Builder', 2\\n              UNION ALL SELECT 'Platform Tool', 3\\n            ) b\\n            LEFT JOIN (\\n              SELECT agent_category,\\n                     MEASURE(total_consumption_credits) AS credits,\\n                     MEASURE(total_consumption_cost_eur) AS cost_eur\\n              FROM silver.metric_credit_consumption\\n              GROUP BY agent_category\\n            ) c ON b.agent_category = c.agent_category\\n            ORDER BY b.sort_order\"}, {\"dataset\": \"ds_top10_agents\", \"kind\": \"config.source\", \"sql\": \"SELECT agent_name,\\n                   agent_category,\\n                   ROUND(MEASURE(total_consumption_credits), 1) AS credits,\\n                   ROUND(MEASURE(total_consumption_cost_eur), 2) AS cost_eur\\n            FROM silver.metric_credit_consumption\\n            WHERE agent_category <> 'Platform Tool'\\n            GROUP BY agent_name, agent_category\\n            ORDER BY credits DESC\\n            LIMIT 10\"}, {\"dataset\": \"ds_studio_user_consumption\", \"kind\": \"config.source\", \"sql\": \"SELECT user_email,\\n                   ROUND(MEASURE(total_consumption_credits), 1) AS credits,\\n                   ROUND(MEASURE(total_consumption_cost_eur), 2) AS cost_eur\\n            FROM silver.metric_credit_consumption\\n            WHERE agent_category = 'Copilot Studio'\\n            GROUP BY user_email\\n            ORDER BY credits DESC\\n            LIMIT 10\"}, {\"dataset\": \"ds_studio_agents_base\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              agent_key,\\n              agent_name,\\n              created_by,\\n              environment_name,\\n              model,\\n              platform,\\n              status,\\n              authentication,\\n              orchestration,\\n              created_on_date,\\n              created_on_eu,\\n              is_no_auth\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n              AND platform = 'Copilot Studio'\\n              AND environment_name IS NOT NULL\"}, {\"dataset\": \"ds_builder_agents_base\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              agent_key,\\n              agent_name,\\n              created_by,\\n              environment_name,\\n              model,\\n              platform,\\n              status,\\n              orchestration,\\n              created_on_date,\\n              created_on_eu,\\n              is_no_auth\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n              AND platform = 'Agent Builder'\"}, {\"dataset\": \"ds_builder_top_makers\", \"kind\": \"config.source\", \"sql\": \"SELECT created_by AS maker_name,\\n                   COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent AND platform = 'Agent Builder'\\n            GROUP BY created_by\"}, {\"dataset\": \"ds_studio_deep_dive\", \"kind\": \"config.source\", \"sql\": \"SELECT platform, agent_name, created_by, environment_name AS environment,\\n                   status, authentication, orchestration, created_on_date, created_on_eu\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent AND platform = 'Copilot Studio'\\n            ORDER BY created_on_date DESC\"}, {\"dataset\": \"ds_builder_deep_dive\", \"kind\": \"config.source\", \"sql\": \"SELECT platform, agent_name, created_by, environment_name AS environment,\\n                   status, model, orchestration, created_on_date, created_on_eu\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent AND platform = 'Agent Builder'\\n            ORDER BY created_on_date DESC\"}, {\"dataset\": \"ds_add_adoption_env_region\", \"kind\": \"config.source\", \"sql\": \"SELECT environment_region, COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n            GROUP BY environment_region\\n            ORDER BY agent_count DESC\"}, {\"dataset\": \"ds_add_adoption_env_type\", \"kind\": \"config.source\", \"sql\": \"SELECT environment_type, COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent AND environment_type IS NOT NULL\\n            GROUP BY environment_type\\n            ORDER BY agent_count DESC\"}, {\"dataset\": \"ds_add_adoption_managed\", \"kind\": \"config.source\", \"sql\": \"SELECT CASE WHEN is_managed THEN 'Managed' ELSE 'Unmanaged' END AS env_mgmt,\\n                   COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n            GROUP BY is_managed\\n            ORDER BY env_mgmt\"}, {\"dataset\": \"ds_add_adoption_model\", \"kind\": \"config.source\", \"sql\": \"SELECT model, COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n            GROUP BY model\\n            ORDER BY agent_count DESC\"}, {\"dataset\": \"ds_add_adoption_orchestration\", \"kind\": \"config.source\", \"sql\": \"SELECT orchestration, COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n            GROUP BY orchestration\\n            ORDER BY agent_count DESC\"}, {\"dataset\": \"ds_add_adoption_utilization\", \"kind\": \"config.source\", \"sql\": \"SELECT 'Used (credit-linked)' AS usage_category,\\n                   MEASURE(used_agent_count) AS agent_count\\n            FROM silver.metric_agent_governance\\n            UNION ALL\\n            SELECT 'Dormant (no measurable credit)', MEASURE(dormant_agent_count)\\n            FROM silver.metric_agent_governance\"}, {\"dataset\": \"ds_add_cost_billed_absorbed\", \"kind\": \"config.source\", \"sql\": \"SELECT 'Billed (prepaid pool)' AS category,\\n                   MEASURE(billed_credits) AS credits,\\n                   ROUND(MEASURE(billed_credits) * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2) AS cost_eur\\n            FROM silver.metric_agent_feature_credit\\n            UNION ALL\\n            SELECT 'Absorbed (license/included)',\\n                   ROUND(MEASURE(non_billed_credits), 1),\\n                   ROUND(MEASURE(non_billed_credits) * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2)\\n            FROM silver.metric_agent_feature_credit\"}, {\"dataset\": \"ds_add_cost_burndown\", \"kind\": \"config.source\", \"sql\": \"SELECT usage_date_eu AS date_eu,\\n                   usage_date AS date,\\n                   SUM(prepaid_consumed_quantity) AS daily_credits,\\n                   ROUND(SUM(prepaid_consumed_quantity) * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2) AS daily_cost_eur\\n            FROM silver.fact_environment_credit\\n            GROUP BY usage_date_eu, usage_date\\n            ORDER BY usage_date\"}, {\"dataset\": \"ds_add_cost_by_license\", \"kind\": \"config.source\", \"sql\": \"SELECT CASE WHEN m365_copilot_licensed THEN 'M365 Copilot licensed' ELSE 'Not licensed' END AS license_status,\\n                   COUNT(DISTINCT user_email) AS users,\\n                   ROUND(MEASURE(total_consumption_credits), 1) AS credits,\\n                   ROUND(MEASURE(total_consumption_cost_eur), 2) AS cost_eur\\n            FROM silver.metric_credit_consumption\\n            GROUP BY m365_copilot_licensed\\n            ORDER BY license_status\"}, {\"dataset\": \"ds_add_cost_headline\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              ROUND(MEASURE(total_consumption_credits), 1) AS total_credits,\\n              ROUND(MEASURE(total_consumption_cost_eur), 2) AS total_cost_eur\\n            FROM silver.metric_credit_consumption\"}, {\"dataset\": \"ds_add_cost_product\", \"kind\": \"config.source\", \"sql\": \"SELECT product,\\n                   ROUND(MEASURE(total_credits), 1) AS credits,\\n                   ROUND(MEASURE(total_cost_eur), 2) AS cost_eur\\n            FROM silver.metric_agent_feature_credit\\n            GROUP BY product\\n            ORDER BY credits DESC\"}, {\"dataset\": \"ds_add_cost_runrate\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date), 1) AS avg_daily_credits,\\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date) * 30, 0) AS projected_monthly_credits,\\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date) * 30 * (SELECT MAX(credit_to_eur) FROM silver.ref_credit_rate), 2) AS projected_monthly_eur\\n            FROM silver.fact_environment_credit\"}, {\"dataset\": \"ds_add_gov_health\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              MEASURE(valid_agent_count) AS valid_agents,\\n              MEASURE(at_risk_agent_count) AS at_risk_agents,\\n              ROUND(100.0 * MEASURE(at_risk_agent_count) / MEASURE(total_agent_count), 1) AS risk_rate_pct,\\n              ROUND(100.0 * MEASURE(dormant_agent_count) / MEASURE(valid_agent_count), 1) AS dormant_rate_pct\\n            FROM silver.metric_agent_governance\"}, {\"dataset\": \"ds_add_gov_lifecycle\", \"kind\": \"config.source\", \"sql\": \"SELECT 'Created (valid)' AS stage, MEASURE(valid_agent_count) AS agent_count\\n            FROM silver.metric_agent_governance\\n            UNION ALL\\n            SELECT 'Published', MEASURE(published_agent_count)\\n            FROM silver.metric_agent_governance\\n            UNION ALL\\n            SELECT 'Used (credit-linked)', MEASURE(used_agent_count)\\n            FROM silver.metric_agent_governance\"}, {\"dataset\": \"ds_add_gov_owner_risk\", \"kind\": \"config.source\", \"sql\": \"SELECT created_by, COUNT(DISTINCT agent_key) AS at_risk_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent\\n              AND (is_no_auth OR NOT is_managed)\\n            GROUP BY created_by\\n            ORDER BY at_risk_count DESC\\n            LIMIT 15\"}, {\"dataset\": \"ds_add_gov_remediation\", \"kind\": \"config.source\", \"sql\": \"SELECT agent_name, platform, created_by, environment_name, status,\\n                   authentication, usage_status, created_on_date, created_on_eu,\\n                   concat_ws(', ',\\n                     CASE WHEN is_no_auth THEN 'No Auth' END,\\n                     CASE WHEN NOT is_valid_agent THEN 'No Owner' END,\\n                     CASE WHEN is_valid_agent AND NOT is_managed THEN 'Unmanaged Env' END,\\n                     CASE WHEN is_valid_agent AND coalesce(status, '-') <> 'Available' THEN 'Draft' END) AS risk_reasons,\\n                   greatest(\\n                     CASE WHEN is_no_auth THEN 3 ELSE 0 END,\\n                     CASE WHEN NOT is_valid_agent THEN 2 ELSE 0 END,\\n                     CASE WHEN is_valid_agent AND NOT is_managed THEN 1 ELSE 0 END) AS severity\\n            FROM silver.vw_agent_governance\\n            WHERE is_no_auth\\n               OR (NOT is_valid_agent)\\n               OR (is_valid_agent AND NOT is_managed)\\n            ORDER BY severity DESC, agent_name\"}, {\"dataset\": \"ds_add_gov_risk_by_env\", \"kind\": \"config.source\", \"sql\": \"SELECT environment_name, 'No Authentication' AS risk_category,\\n                   COUNT(DISTINCT agent_key) AS agent_count\\n            FROM silver.vw_agent_governance\\n            WHERE is_no_auth AND environment_name IS NOT NULL\\n            GROUP BY environment_name\\n            UNION ALL\\n            SELECT environment_name, 'Orphaned / No Owner', COUNT(DISTINCT agent_key)\\n            FROM silver.vw_agent_governance\\n            WHERE NOT is_valid_agent AND environment_name IS NOT NULL\\n            GROUP BY environment_name\\n            UNION ALL\\n            SELECT environment_name, 'Unmanaged Environment', COUNT(DISTINCT agent_key)\\n            FROM silver.vw_agent_governance\\n            WHERE is_valid_agent AND NOT is_managed AND environment_name IS NOT NULL\\n            GROUP BY environment_name\"}, {\"dataset\": \"ds_add_gov_risk_category\", \"kind\": \"config.source\", \"sql\": \"SELECT 'No Authentication' AS risk_category, MEASURE(no_auth_count) AS agent_count\\n            FROM silver.metric_agent_governance\\n            UNION ALL\\n            SELECT 'Orphaned / No Owner', MEASURE(orphan_agent_count)\\n            FROM silver.metric_agent_governance\\n            UNION ALL\\n            SELECT 'Unmanaged Environment', MEASURE(unmanaged_env_agent_count)\\n            FROM silver.metric_agent_governance\"}, {\"dataset\": \"ds_usage_copilot_metrics\", \"kind\": \"asset_name\", \"sql\": \"SELECT\\n  MEASURE(`Total Interactions`) AS total_interactions,\\n  MEASURE(`Unique Active Users`) AS unique_active_users,\\n  MEASURE(`BizChat M365 Interactions`) AS bizchat_m365\\nFROM silver.copilot_analytics_metrics\"}, {\"dataset\": \"ds_kb_coverage\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              agent_id,\\n              environment_name,\\n              is_valid_studio,\\n              has_knowledge_sources,\\n              is_detail_unavailable\\n            FROM silver.vw_agent_knowledge\"}, {\"dataset\": \"ds_kb_detail\", \"kind\": \"config.source\", \"sql\": \"SELECT\\n              agent_id,\\n              agent_name,\\n              agent_owner,\\n              environment_name,\\n              kb_key,\\n              kb_display_name,\\n              kb_type,\\n              kb_value,\\n              kb_agent_count,\\n              is_shared,\\n              in_inventory\\n            FROM silver.fact_agent_knowledge_source\"}, {\"dataset\": \"ds_bot_usage\", \"kind\": \"asset_name\", \"sql\": \"SELECT\\n  MEASURE(`total_conversations`) AS total_conversations,\\n  MEASURE(`total_agents`) AS total_agents,\\n  MEASURE(`active_agents_30d`) AS active_agents_30d\\nFROM silver.bot_usage_metrics\"}, {\"dataset\": \"ds_consumption_declining\", \"kind\": \"queryLines\", \"sql\": \"WITH ref AS (\\n  SELECT\\n    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\\n  FROM\\n    silver.bot_usage\\n),\\nagent_month AS (\\n  SELECT\\n    bot_name,\\n    DATE_TRUNC('MONTH', usage_date) AS month,\\n    SUM(conversations) AS convs\\n  FROM\\n    silver.bot_usage\\n  GROUP BY\\n    bot_name,\\n    DATE_TRUNC('MONTH', usage_date)\\n)\\nSELECT\\n  cur.bot_name,\\n  prev.convs AS prior_month,\\n  COALESCE(cur2.convs, 0) AS last_full_month,\\n  ROUND((COALESCE(cur2.convs, 0) - prev.convs) * 100.0 / prev.convs, 1) AS change_pct\\nFROM\\n  (\\n    SELECT DISTINCT\\n      bot_name\\n    FROM\\n      agent_month\\n  ) cur\\n    CROSS JOIN ref r\\n    JOIN agent_month prev\\n      ON prev.bot_name = cur.bot_name\\n      AND prev.month = ADD_MONTHS(r.current_month, -2)\\n    LEFT JOIN agent_month cur2\\n      ON cur2.bot_name = cur.bot_name\\n      AND cur2.month = ADD_MONTHS(r.current_month, -1)\\nWHERE\\n  prev.convs >= 10\\n  AND COALESCE(cur2.convs, 0) < prev.convs * 0.5\\nORDER BY\\n  change_pct\"}, {\"dataset\": \"ds_consumption_abandoned\", \"kind\": \"queryLines\", \"sql\": \"WITH ref AS (\\n  SELECT\\n    MAX(usage_date) AS max_dt\\n  FROM\\n    silver.bot_usage\\n)\\nSELECT\\n  b.bot_name,\\n  SUM(b.conversations) AS lifetime_conversations,\\n  COUNT(DISTINCT b.usage_date) AS lifetime_active_days,\\n  MAX(b.usage_date) AS last_used,\\n  DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use\\nFROM\\n  silver.bot_usage b CROSS JOIN ref r\\nGROUP BY\\n  b.bot_name,\\n  r.max_dt\\nHAVING\\n  SUM(b.conversations) >= 20\\n  AND MAX(b.usage_date) < DATE_SUB(r.max_dt, 60)\\nORDER BY\\n  lifetime_conversations DESC\"}, {\"dataset\": \"ds_consumption_mom\", \"kind\": \"queryLines\", \"sql\": \"WITH monthly AS (\\n  SELECT\\n    DATE_TRUNC('MONTH', usage_date) AS month,\\n    SUM(conversations) AS convs\\n  FROM\\n    silver.bot_usage\\n  GROUP BY\\n    DATE_TRUNC('MONTH', usage_date)\\n),\\nref AS (\\n  SELECT\\n    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\\n  FROM\\n    silver.bot_usage\\n)\\nSELECT\\n  prev.convs AS prior_month_conversations,\\n  cur.convs AS last_full_month_conversations,\\n  ROUND((cur.convs - prev.convs) * 100.0 / prev.convs, 1) AS mom_growth_pct\\nFROM\\n  ref r\\n    JOIN monthly cur\\n      ON cur.month = ADD_MONTHS(r.current_month, -1)\\n    JOIN monthly prev\\n      ON prev.month = ADD_MONTHS(r.current_month, -2)\"}, {\"dataset\": \"ds_consumption_agent_detail\", \"kind\": \"queryLines\", \"sql\": \"WITH ref AS (\\n  SELECT\\n    MAX(usage_date) AS max_dt\\n  FROM\\n    silver.bot_usage\\n),\\nbot_status AS (\\n  SELECT\\n    b.bot_name,\\n    CASE\\n      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 30) THEN 'Active (last 30 days)'\\n      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 60) THEN 'Idle (31-60 days)'\\n      ELSE 'Dormant (60+ days)'\\n    END AS usage_status,\\n    MIN(b.usage_date) AS first_used,\\n    MAX(b.usage_date) AS last_used,\\n    DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use,\\n    COUNT(DISTINCT b.usage_date) AS active_days,\\n    ROUND(AVG(b.conversations), 2) AS avg_conversations_per_bot_day\\n  FROM\\n    silver.bot_usage b CROSS JOIN ref r\\n  GROUP BY\\n    b.bot_name,\\n    r.max_dt\\n)\\nSELECT\\n  b.bot_name,\\n  b.environment,\\n  CASE\\n    WHEN b.environment LIKE '%PROD%' THEN 'Production'\\n    WHEN LOWER(b.environment) LIKE '%default%' THEN 'Default environment'\\n    ELSE 'Dev / Test / Other'\\n  END AS environment_type,\\n  DATE_TRUNC('MONTH', b.usage_date) AS usage_month,\\n  DATE_TRUNC('QUARTER', b.usage_date) AS usage_quarter,\\n  CONCAT(\\n    YEAR(DATE_TRUNC('QUARTER', b.usage_date)),\\n    ' Q',\\n    QUARTER(DATE_TRUNC('QUARTER', b.usage_date))\\n  ) AS quarter_label,\\n  SUM(b.conversations) AS conversations,\\n  s.usage_status,\\n  s.first_used,\\n  s.last_used,\\n  s.days_since_last_use,\\n  s.active_days,\\n  s.avg_conversations_per_bot_day\\nFROM\\n  silver.bot_usage b\\n    JOIN bot_status s\\n      ON s.bot_name = b.bot_name\\nGROUP BY\\n  b.bot_name,\\n  b.environment,\\n  DATE_TRUNC('MONTH', b.usage_date),\\n  DATE_TRUNC('QUARTER', b.usage_date),\\n  s.usage_status,\\n  s.first_used,\\n  s.last_used,\\n  s.days_since_last_use,\\n  s.active_days,\\n  s.avg_conversations_per_bot_day\"}]")
